-- Complete the admin-editable email catalog. Existing templates are preserved;
-- this migration only creates types that previously fell back to hard-coded mail.
WITH defaults(type, name, description, subject, html_content, text_content, available_variables) AS (
  VALUES
    ('project_request_created', 'Notification — Project request', 'New project request notification', 'New project request: {{request_title}}', '<h1>New project request</h1><p><strong>{{request_title}}</strong></p><p>{{request_description}}</p><p><a href="{{request_url}}">Open request</a></p>', 'New project request: {{request_title}}\n{{request_url}}', '["request_title","request_description","request_url","company_name","created_by_name"]'::jsonb),
    ('project_request_feedback_created', 'Notification — Project request feedback', 'New project request feedback notification', 'New feedback: {{request_title}}', '<h1>New project request feedback</h1><p><strong>{{request_title}}</strong></p><p>{{feedback}}</p><p><a href="{{request_url}}">Open request</a></p>', 'New feedback: {{request_title}}\n{{request_url}}', '["request_title","feedback","request_url","company_name","created_by_name"]'::jsonb),
    ('proposal_sent', 'Notification — Proposal sent', 'Proposal sent notification', 'Proposal sent: {{proposal_title}}', '<h1>Proposal sent</h1><p><strong>{{proposal_title}}</strong></p><p><a href="{{proposal_url}}">Review proposal</a></p>', 'Proposal sent: {{proposal_title}}\n{{proposal_url}}', '["proposal_title","proposal_url","company_name"]'::jsonb),
    ('proposal_accepted', 'Notification — Proposal accepted', 'Proposal acceptance notification', 'Proposal accepted: {{proposal_title}}', '<h1>Proposal accepted</h1><p><strong>{{proposal_title}}</strong> was accepted.</p><p><a href="{{proposal_url}}">Open proposal</a></p>', 'Proposal accepted: {{proposal_title}}\n{{proposal_url}}', '["proposal_title","proposal_url","company_name"]'::jsonb),
    ('proposal_rejected', 'Notification — Proposal rejected', 'Proposal rejection notification', 'Proposal rejected: {{proposal_title}}', '<h1>Proposal rejected</h1><p><strong>{{proposal_title}}</strong> was rejected.</p><p><a href="{{proposal_url}}">Open proposal</a></p>', 'Proposal rejected: {{proposal_title}}\n{{proposal_url}}', '["proposal_title","proposal_url","company_name"]'::jsonb),
    ('proposal_feedback_created', 'Notification — Proposal feedback', 'New proposal feedback notification', 'New proposal feedback: {{proposal_title}}', '<h1>New proposal feedback</h1><p><strong>{{proposal_title}}</strong></p><p>{{feedback}}</p><p><a href="{{proposal_url}}">Open proposal</a></p>', 'New proposal feedback: {{proposal_title}}\n{{proposal_url}}', '["proposal_title","feedback","proposal_url","company_name"]'::jsonb),
    ('support_ticket_created', 'Notification — Support ticket', 'New support ticket notification', 'New support ticket: {{ticket_subject}}', '<h1>New support ticket</h1><p><strong>{{ticket_subject}}</strong></p><p>{{ticket_description}}</p><p><a href="{{ticket_url}}">Open ticket</a></p>', 'New support ticket: {{ticket_subject}}\n{{ticket_url}}', '["ticket_subject","ticket_description","ticket_url","company_name","created_by_name"]'::jsonb),
    ('invoice_paid', 'Invoice — Paid', 'Invoice paid notification', 'Invoice paid: {{invoice_number}}', '<h1>Invoice paid</h1><p>{{invoice_number}} has been paid.</p><p>Amount: {{amount}}</p>', 'Invoice paid: {{invoice_number}}\nAmount: {{amount}}', '["invoice_number","amount","company_name"]'::jsonb),
    ('invoice_payment_failed', 'Invoice — Payment failed', 'Internal payment failure notification', 'Payment failed: {{invoice_number}}', '<h1>Payment failed</h1><p>Payment failed for {{invoice_number}}.</p><p>Amount: {{amount}}</p>', 'Payment failed: {{invoice_number}}\nAmount: {{amount}}', '["invoice_number","amount"]'::jsonb),
    ('invoice_refunded', 'Invoice — Refunded', 'Refund notification', 'Invoice refunded: {{invoice_number}}', '<h1>Invoice refunded</h1><p>{{invoice_number}} was refunded.</p><p>Amount: {{amount}}</p>', 'Invoice refunded: {{invoice_number}}\nAmount: {{amount}}', '["invoice_number","amount"]'::jsonb),
    ('subscription_updated', 'Notification — Subscription updated', 'Subscription change notification', 'Subscription updated for {{company_name}}', '<h1>Subscription updated</h1><p>The subscription for {{company_name}} is now {{subscription_status}}.</p>', 'Subscription updated for {{company_name}}: {{subscription_status}}', '["company_name","subscription_status"]'::jsonb),
    ('contract_expiring', 'Contract — Expiring', 'Contract expiration reminder', 'Contract expiring: {{contract_title}}', '<h1>Contract expiring</h1><p><strong>{{contract_title}}</strong> ({{contract_number}}) ends on {{end_date}}.</p><p><a href="{{contract_url}}">View contract</a></p>', 'Contract expiring: {{contract_title}}\n{{contract_url}}', '["contract_title","contract_number","end_date","company_name","days_until_expiration","contract_url"]'::jsonb),
    ('contract_expiring_urgent', 'Contract — Expiring soon', 'Urgent contract expiration reminder', 'Urgent: contract expiring: {{contract_title}}', '<h1>Contract expiring soon</h1><p><strong>{{contract_title}}</strong> ends on {{end_date}}.</p><p><a href="{{contract_url}}">View contract</a></p>', 'Urgent contract expiring: {{contract_title}}\n{{contract_url}}', '["contract_title","contract_number","end_date","company_name","days_until_expiration","contract_url"]'::jsonb),
    ('sla_warning', 'SLA — Warning', 'SLA deadline warning', 'SLA warning: {{request_title}}', '<h1>SLA deadline approaching</h1><p><strong>{{request_title}}</strong> has {{time_remaining_hours}} hours remaining.</p><p><a href="{{request_url}}">Open request</a></p>', 'SLA warning: {{request_title}}\n{{request_url}}', '["request_title","request_number","request_priority","time_remaining_hours","request_url"]'::jsonb),
    ('sla_breach', 'SLA — Breach', 'SLA breach notification', 'SLA breached: {{request_title}}', '<h1>SLA breached</h1><p><strong>{{request_title}}</strong> has exceeded its SLA.</p><p><a href="{{request_url}}">Open request</a></p>', 'SLA breached: {{request_title}}\n{{request_url}}', '["request_title","request_number","request_priority","response_time_hours","resolution_time_hours","request_url"]'::jsonb)
)
INSERT INTO email_templates (name, description, type, subject, html_content, text_content, available_variables, is_default, is_active)
SELECT d.name, d.description, d.type, d.subject, d.html_content, d.text_content, d.available_variables, true, true
FROM defaults d
WHERE NOT EXISTS (SELECT 1 FROM email_templates e WHERE e.type = d.type AND e.deleted_at IS NULL);
